<div class="dp-highlighter"><div class="bar"><div class="tools"> </div></div><ol class="dp-xml" start="1"><li class="alt"><span><span class="attribute">arr1</span><span> = [1, 2, 3, 4, 5];  </span></span></li><li><span><span class="attribute">arr2</span><span> = [None] * len(arr1);  </span></span></li></ol></div><textarea class="xml" name="code" style="display:none">arr1 = [1, 2, 3, 4, 5];
